import assert from 'node:assert/strict';import {createRequire} from 'node:module';import {resolve} from 'node:path';import {pathToFileURL} from 'node:url';import {mkdir,writeFile} from 'node:fs/promises';
const require=createRequire(import.meta.url),{chromium}=require('C:/Users/genki/.cache/codex-runtimes/codex-primary-runtime/dependencies/node/node_modules/playwright-core');
const evidence=resolve('../../outputs/verification-v34-pitch-chart-contact-v1');await mkdir(evidence);
const browser=await chromium.launch({executablePath:'C:/Program Files/Google/Chrome/Application/chrome.exe',headless:true});
try{
 const page=await browser.newPage({viewport:{width:1200,height:860}});await page.goto(pathToFileURL(resolve('../../outputs/ばせぼーるlv33_TBD_vs_LAD_Core試合版.html')).href);await page.evaluate(()=>document.fonts.ready);await page.addScriptTag({path:resolve('tools/browser-bridge/live-pitch-chart.js')});
 const result=await page.evaluate(()=>{
  document.getElementById('managed-team').value='1';document.getElementById('batting-choice').value='balanced';document.getElementById('pitch-choice').value='curve';
  for(let i=0;i<8;i++){document.getElementById('next-pitch').click();window.liveMatchPlayback.stop();const s=window.liveMatchPlayback.inspect();if(s.error)throw Error(s.error);if(s.lastResult.play.contactMoment)break;}
  const s=window.liveMatchPlayback.inspect(),records=s.host.history,index=records.findIndex(r=>r.play.contactMoment),record=records[index];if(!record)throw Error('actual contact required');
  const api=window.KneekuraLivePitchChart.create({canvas:document.getElementById('pitch-chart'),caption:document.getElementById('chart-caption'),core:window.KneekuraNativeMatchCore});
  const height=JSON.parse(document.getElementById('match-data').textContent).players[record.batterPlayerId].height;
  const observed=api.observe({records,pitchIndex:index,atTick:record.play.rules.endedAtTick,batterHeightMeters:height});api.draw(observed);
  const entry=observed.history.find(e=>e.pitchId==='live-pitch-'+index),mark=api.inspect().chartMarks.find(e=>e.pitchId===entry.pitchId);
  const poison={...record,play:{...record.play,rules:{...record.play.rules,endedAtTick:record.play.rules.endedAtTick+1000000},get diagnostics(){throw Error('future Source read');}}};
  const nofuture=api.observe({records:[record,poison],pitchIndex:0,atTick:record.play.rules.endedAtTick,batterHeightMeters:height});
  return {count:records.length,index,kind:entry.location.kind,location:entry.location.position,actual:record.play.contactMoment.ball.position,evidence:observed.locations.find(e=>e.pitchId===entry.pitchId),
   shape:mark?.shape,expectedAngle:Math.atan2(-entry.breakVector.y*204,entry.breakVector.x*290),pitchKind:entry.pitchKind,
   nofutureEntries:nofuture.history.length,options:[...document.getElementById('pitch-choice').options].map(o=>o.value)};
 });
 assert.equal(result.kind,'contact');assert.deepEqual(result.location,result.actual);assert.equal(result.evidence.method,'CORE_CONTACT_MOMENT');assert.equal(result.nofutureEntries,1);assert.equal(result.pitchKind,'curve');assert.equal(result.shape.family,'triangle');assert(Math.abs(result.shape.angle-result.expectedAngle)<1e-12);
 await page.locator('#pitch-chart').screenshot({path:resolve(evidence,'core-contact-chart.png')});await writeFile(resolve(evidence,'contact-check.json'),JSON.stringify({status:'PASS',...result},null,2)+'\n');console.log(JSON.stringify({status:'PASS',kind:result.kind,pointExact:true,triangleUsesSourceDirection:true,futureSourceUnread:true,evidence}));
 await page.close();
}finally{await browser.close();}
